package com.mrsrik.ai_powered_commerce.common.error;

/**
 * Names of database UNIQUE constraints that services translate into specific API errors.
 *
 * <p>Names generated by PostgreSQL for unnamed UNIQUE columns follow
 * {@code <table>_<column>_key}. Every value is verified against the migrated schema by
 * {@code ConstraintNamesIT}. Use with {@link ConstraintViolations#constraintName(Throwable)}.
 */
public final class ConstraintNames {

    /** users(external_auth_id): maps to ALREADY_REGISTERED on registration. */
    public static final String USERS_EXTERNAL_AUTH_ID = "users_external_auth_id_key";

    /** users(email): maps to EMAIL_ALREADY_REGISTERED on registration. */
    public static final String USERS_EMAIL = "users_email_key";

    /** products(sku): maps to DUPLICATE_SKU on product create/update. */
    public static final String PRODUCTS_SKU = "products_sku_key";

    /** categories(name): maps to DUPLICATE_CATEGORY_NAME on category create/update. */
    public static final String CATEGORIES_NAME = "categories_name_key";

    /** orders(transaction_id): triggers one retry of transaction id generation at checkout. */
    public static final String ORDERS_TRANSACTION_ID = "uq_orders_transaction_id";

    /** carts(user_id): lost race when lazily creating a cart; re-read the existing cart. */
    public static final String CARTS_USER_ID = "carts_user_id_key";

    /** cart_items(cart_id, product_id): lost race when adding the same product; merge quantity. */
    public static final String CART_ITEMS_CART_PRODUCT = "uq_cart_id_product";

    private ConstraintNames() {
    }
}
